'use strict';
const mechanismCache=new Map();
function equipmentData(ids){return {...D,baseSlots:Q.base(D,ids)};}
function mechanicAnalysis(ids,baseSlots=Q.base(D,ids)){const horizon=typeof timingHorizon==='undefined'?60:timingHorizon,key=JSON.stringify([ids,baseSlots,horizon]);if(!mechanismCache.has(key)){if(mechanismCache.size>250)mechanismCache.clear();mechanismCache.set(key,DosulMechanics.analyze({...D,baseSlots},ids,horizon));}return mechanismCache.get(key);}
function mechanicOptions(options){const mode=$('#mechanism-filter')?.value||'all',sort=$('#candidate-sort')?.value||'effect';return DosulMechanics.sort(options.filter(x=>DosulMechanics.matches(x.skill,mode)).map(x=>{const plan=Q.place(D,build,step,x.skill.id,insertMode?'insert':'replace');return {...x,mechanics:mechanicAnalysis(plan.ids,plan.baseSlots)};}),sort);}
function mechanicFacts(s){const f=DosulMechanics.facts(s);return `<span class="mechanic-facts"><span>동작 <b>${f.motion===null?'미확인':f.motion+'초'}</b></span><span>저장 <b>${f.charges}회</b></span>${f.charges>1?'<span>순차 충전※</span>':''}</span>`;}
function metricTime(n){return n===null?'구간 내 미발동':Math.round(n*10)/10+'초';}
function mechanicCard(x){const a=x.mechanics;if(!a)return '';const base=mechanicAnalysis(build),delta=(v,b,unit)=>v===null?'계산 보류':`${v}${unit}${b!==null?` (${v-b>0?'+':''}${v-b})`:''}`;
 return `<div class="mechanic-comparison">${mechanicFacts(x.skill)}${!a.valid?'<span class="warn">'+esc(a.missing.concat(a.issues).join(' · '))+'</span>':`<span>배치 후 · 신식 <b>${a.sim.active.join('·')||'미개방'}</b> · 첫 발동 <b>${metricTime(a.first)}</b></span><span>${a.sim.horizon}초 사용 <b>${delta(a.casts,base.casts,'회')}</b> · 신식 유지 중 적중 <b>${delta(a.buffed,base.buffed,'회')}</b></span><span>궁극기 강화 구간 <b>${a.ultBuffed}/${a.ultCasts}회</b> · 신식으로 추가 사용 <b>${a.extra>0?'+':''}${a.extra}회</b></span>${a.strength?`<span>신식 포함 예정 피해계수 <b>${a.strength.power.toFixed(0)}</b> · 강화분 <b>+${a.strength.gainPct}%</b></span>`:''}${a.starved.length?`<span class="warn">관찰 구간 내 미사용 ${a.starved.map(id=>esc(byId(id).name)).join('·')}</span>`:''}`}</div>`;
}
function renderMechanics(){const host=$('#mechanics-summary');if(!host)return;host.hidden=!build.length;if(!build.length){host.innerHTML='';return;}const a=mechanicAnalysis(build);renderMarkup('#mechanics-summary',`<div class="mechanics-current"><b>현재 조합 · ${a.sim.horizon}초 예상</b><span>신식 <strong>${a.sim.active.join('·')||'미개방'}</strong></span><span>첫 발동 <strong>${a.valid?metricTime(a.first):'계산 보류'}</strong></span><span>도술 사용 <strong>${a.casts??'—'}회</strong></span><span>신식 추가 <strong>${a.extra??'—'}회</strong></span><span>신식 유지 중 궁극기 <strong>${a.ultBuffed??'—'}/${a.ultCasts}회</strong></span></div>${a.strength?`<div class="mechanics-current"><span>신식 포함 예정 피해계수 <strong>${a.strength.power.toFixed(0)}</strong> · 강화분 +${a.strength.gainPct}%</span>${a.strength.timeline.map(t=>`<span>${esc(t.family)} ${t.hasWindow?'유지 '+t.seconds+'초 · '+t.uptimePct+'%':'지속 구간 없음'}</span>`).join('')}</div>`:''}<small>후보의 괄호는 현재 조합 대비 증감 · 신식 추가는 같은 조합의 신식 미적용 대비 · 피해계수는 모든 예정 타격이 단일 대상에 적중하는 참고값이며 실전 DPS가 아님</small><details class="mechanics-details"><summary>도술별 사용 횟수·초기화 이득·계산 조건</summary>${!a.valid?`<p class="warn">${esc(a.issues.concat(a.missing).join(' · '))}</p>`:''}<table><thead><tr><th>도술</th><th>신식 미적용</th><th>적용</th><th>증감</th></tr></thead><tbody>${build.map(id=>`<tr><td>${esc(byId(id).name)}</td><td>${a.without[id]||0}회</td><td>${a.perSkill[id]||0}회</td><td>${(a.perSkill[id]||0)-(a.without[id]||0)}회</td></tr>`).join('')}</tbody></table>${a.resets.map(r=>`<p><b>${metricTime(r.time)} ${esc(r.name)}</b> · ${r.changes.map(c=>`${esc(byId(c.id).name)} 남은 ${Math.max(0,Math.round((c.before-r.time)*10)/10)}초`).join(' / ')}</p>`).join('')||'<p>관찰 구간 내 쿨타임 초기화 없음</p>'}<p>기본 장착 5칸의 같은 계열 3개로 신식을 판정합니다. 사용 가능한 앞순위부터 실행하며 기본 수치·최대 차지·시작 시 저장 횟수 가득을 가정합니다. 저장 횟수는 순차 충전, 초기화 시 일반 도술의 저장 횟수를 모두 회복하는 참고 모델입니다.</p><p>강화 구간은 신식 유지 중의 예상 적중 횟수이며, 피해 증가량이나 DPS 점수가 아닙니다. 효과별 상세 적용 대상과 적중 프레임은 별도 확인이 필요합니다. 체력 조건·이동·피격·처치·장비·돌파는 계산에 포함하지 않습니다. 파멸 영력은 상세의 25를 적용하며 요약의 15와 불일치합니다.</p><p><a href="https://kkaebigg.com/skills/" target="_blank" rel="noopener">도술·신식 참고 자료</a> · 버그는 계산에서 무시하고 기존 유무 표기를 유지합니다.</p></details>`);}
function renderEquipment(){const host=$('#equipment-control');if(!host)return;D.baseSlots=Q.base(D,build);const normal=build.map(byId).filter(s=>!s.ultimate),counts=Q.baseCounts(D,build);renderMarkup('#equipment-control',`<summary>기본 장착 <b>${D.baseSlots.length}/5</b> · ${Object.entries(counts).map(([f,n])=>`${f} ${n}`).join(' · ')||'도술 배치 시 자동 채움'} <span>장착 변경</span></summary><div class="equipment-options"><p>기본 5칸에서 같은 계열 3개 → 신식·궁극기 개방. 사용 순서를 바꿔도 장착은 유지됩니다.</p>${normal.map(s=>`<label><input type="checkbox" data-base-slot="${s.id}" ${D.baseSlots.includes(s.id)?'checked':''}>${esc(s.name)} ${styleBadge(s)}</label>`).join('')}<small>기본 장착을 바꾸려면 기존 항목을 해제한 뒤 다른 도술을 선택하세요.</small></div>`);}
